void interrupt NetISR (void)
{
     if (doomcom.command == CMD_SEND)
     {
          localtime++;
          SendPacket (doomcom.remotenode);
     }
	 else if (doomcom.command == CMD_GET)
     {
          GetPacket ();
     }
}

