		  {
		  for(doomcom.intnum = 0x60 ; doomcom.intnum <= 0x66 ;
doomcom.intnum++)
			   {
			   vector = *(char far * far *)(doomcom.intnum*4);
			   if(vector == NULL || *vector == 0xcf)
					break;
			   }
