// A_ReFire
// The player can re-fire the weapon
// without lowering it entirely.
//

chunks.code:
void A_ReFire
( player_t*	player,
  pspdef_t*	psp )
{

    // check for fire
    //  (if a weaponchange is pending, let it go through instead)
    if ( (player->cmd.buttons & BT_ATTACK) 
	 && player->pendingweapon == wp_nochange
	 && player->health)
    {
	player->refire++;
	P_FireWeapon (player);
    }
    else
    {
	player->refire = 0;
	P_CheckAmmo (player);
