// Called when a thing shoots a special line.
//

chunks.code:
void
P_ShootSpecialLine
( mobj_t*	thing,
  line_t*	line )
{
    int		ok;

    //	Impacts that other things can activate.
    if (!thing->player)
    {
	ok = 0;
	switch(line->special)
	{
	  case 46:
	    // OPEN DOOR IMPACT
	    ok = 1;
	    break;
	}
	if (!ok)
	    return;
    }

    switch(line->special)
    {
      case 24:
