  {
    pitch += 16 - (M_Random()&31);

    if (pitch<0)
      pitch = 0;
    else if (pitch>255)
      pitch = 255;
  }

  // kill old sound
  S_StopSound(origin);

  // try to find a channel
  cnum = S_getChannel(origin, sfx);

  if (cnum<0)
    return;

  //
  // This is supposed to handle the loading/caching.

/* ... [22 lines omitted in preview] ... */

#endif

  // increase the usefulness
