	ModemResponse ("OK");

	printf ("\n"STR_DIALING"\n\n");
	p = CheckParm ("-dial");
	sprintf (cmd,"ATDT%s",myargv[p+1]);

	ModemCommand(cmd);
	ModemResponse (STR_CONNECT);
	doomcom.consoleplayer = 1;
}

void Answer (void)
